"""Build draft Scratch SD scaffolding slides without touching production datasets."""
from pathlib import Path
import json, html

ROOT = Path(__file__).resolve().parents[1]
SLIDES = ROOT / "slides"
DRAFT = ROOT / "drafts" / "sd-scratch"
SLIDES.mkdir(exist_ok=True); DRAFT.mkdir(parents=True, exist_ok=True)

CSS = r'''
:root{--ink:#172033;--yellow:#ffd84d;--blue:#42b8e8;--purple:#8b6ee8;--orange:#ff9b54;--green:#62c38a;--paper:#fffdf7;--muted:#5c667a}*{box-sizing:border-box}body{margin:0;background:#eaf4f7;color:var(--ink);font-family:Arial,sans-serif}.app{max-width:1180px;height:100vh;margin:auto;padding:20px;display:flex;flex-direction:column}.top{display:flex;justify-content:space-between;align-items:center;gap:14px}.brand{font-weight:800;letter-spacing:.04em}.tag{background:var(--yellow);border:3px solid var(--ink);border-radius:999px;padding:8px 14px;font-weight:800}.deck{flex:1;min-height:0;margin-top:14px}.slide{display:none;height:100%;background:var(--paper);border:4px solid var(--ink);border-radius:24px;box-shadow:10px 10px 0 var(--ink);padding:clamp(24px,5vw,64px);overflow:auto}.slide.active{display:block;animation:in .25s ease}@keyframes in{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}h1{font-size:clamp(30px,5vw,58px);line-height:1.05;margin:0 0 18px}h2{font-size:clamp(24px,3vw,38px);margin:0 0 20px}h3{margin:10px 0 8px}.lead{font-size:clamp(18px,2vw,25px);line-height:1.45;max-width:850px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px;margin:22px 0}.card{border:3px solid var(--ink);border-radius:16px;padding:18px;background:#fff;box-shadow:5px 5px 0 var(--ink)}.card b{display:block;font-size:20px;margin-bottom:8px}.pill{display:inline-block;border:2px solid var(--ink);border-radius:10px;padding:7px 10px;margin:4px 4px 4px 0;font-weight:800}.event{background:#ffdf55}.motion{background:#55a9ef;color:#fff}.looks{background:#a678df;color:#fff}.control{background:#ffad55}.sense{background:#62c5c9}.data{background:#f39b4e}.code{background:#172033;color:#fff;border-radius:14px;padding:20px;font-family:monospace;font-size:clamp(16px,2vw,22px);line-height:1.55;margin:20px 0}.note{background:#e9f4ff;border-left:8px solid var(--blue);padding:14px 18px;border-radius:10px;margin:18px 0;font-size:18px;line-height:1.45}.warn{background:#fff2c7;border-left:8px solid var(--orange);padding:14px 18px;border-radius:10px;margin:18px 0;font-size:18px;line-height:1.45}ul{font-size:19px;line-height:1.55}.footer{display:flex;justify-content:space-between;align-items:center;margin-top:14px;gap:10px}.btn{border:3px solid var(--ink);background:var(--blue);color:#fff;border-radius:12px;padding:10px 18px;font-size:16px;font-weight:800;cursor:pointer;box-shadow:4px 4px 0 var(--ink)}.btn:active{transform:translate(2px,2px);box-shadow:2px 2px 0 var(--ink)}.counter{font-weight:800;color:var(--muted)}.quiz button{display:block;width:100%;text-align:left;border:2px solid var(--ink);background:white;border-radius:10px;padding:12px;margin:8px 0;font-size:17px;cursor:pointer}.quiz button.correct{background:#c9f4d7}.quiz button.wrong{background:#ffd1d1}.source{font-size:13px;color:var(--muted);margin-top:22px}.source a{color:inherit}@media(max-width:600px){.app{padding:10px}.slide{padding:24px 20px;border-radius:18px;box-shadow:6px 6px 0 var(--ink)}.top{font-size:13px}.footer{position:sticky;bottom:0;background:linear-gradient(transparent,var(--paper) 25%);padding-top:18px}}
'''

def make_html(meta, slides):
    blocks=[]
    for i,s in enumerate(slides):
        blocks.append(f'<section class="slide {"active" if i==0 else ""}" data-title="{html.escape(s["title"])}">{s["body"]}</section>')
    return f'''<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(meta["title"])}</title><style>{CSS}</style></head><body><main class="app"><div class="top"><div class="brand">KALANANTI · SCRATCH SD</div><div class="tag">{html.escape(meta["kicker"])}</div></div><div class="deck">{"".join(blocks)}</div><div class="footer"><button class="btn" id="prev">← Sebelumnya</button><span class="counter">Slide <span id="n">1</span> / <span id="total">{len(slides)}</span></span><button class="btn" id="next">Berikutnya →</button></div></main><script>const ss=[...document.querySelectorAll('.slide')];let i=0;function show(n){{i=Math.max(0,Math.min(ss.length-1,n));ss.forEach((s,j)=>s.classList.toggle('active',j===i));document.querySelector('#n').textContent=i+1;document.querySelector('#prev').disabled=i===0;document.querySelector('#next').disabled=i===ss.length-1}}document.querySelector('#prev').onclick=()=>show(i-1);document.querySelector('#next').onclick=()=>show(i+1);document.addEventListener('keydown',e=>{{if(e.key==='ArrowRight')show(i+1);if(e.key==='ArrowLeft')show(i-1)}});document.querySelectorAll('.quiz button').forEach(b=>b.onclick=()=>{{b.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('correct','wrong'));b.classList.add(b.dataset.correct==='true'?'correct':'wrong')}});show(0);</script></body></html>'''

def s(title, body): return {"title":title,"body":f'<h2>{title}</h2>{body}'}
def card(b, t): return f'<div class="card"><b>{b}</b>{t}</div>'
def quiz(q, opts, answer):
    return '<div class="quiz card"><b>🧠 Cek pemahaman</b><p>'+q+'</p>'+''.join(f'<button data-correct="{"true" if j==answer else "false"}">{chr(65+j)}. {o}</button>' for j,o in enumerate(opts))+'</div>'

