for meta, slides in docs:
    meta = dict(meta, type="slide", level="SD", totalSlides=len(slides), slideUrl=f"./slides/{meta['id']}.html", embedUrl=f"slides/{meta['id']}.html", prerequisiteStepIds=[])
    meta['learningObjectives']=meta.pop('objectives')
    meta['practice']={"type":"guided_reading","description":"Menyelesaikan simulasi mini dan checkpoint pada setiap bagian."}
    meta['completionCriteria']={"quizScoreMin":100,"interactiveCompleted":True,"description":"Menyelesaikan semua slide, latihan, dan kuis dengan benar."}
    meta['bookmarks']=[{"slideIndex":i,"label":x['title']} for i,x in enumerate(slides)]
    meta['quizzes']=[{"question":"Checkpoint tersedia di dalam slide interaktif.","options":["Lihat ulang slide","Coba bloknya","Minta bantuan setelah mencoba"],"answer":0,"explanation":"Baca kembali bagian yang belum jelas lalu coba lagi.","embedded":True}]
    (SLIDES/f"{meta['id']}.html").write_text(make_html(meta, slides), encoding='utf-8')
    (SLIDES/f"{meta['id']}.json").write_text(json.dumps(meta,ensure_ascii=False,indent=2), encoding='utf-8')
    (DRAFT/f"{meta['id']}.json").write_text(json.dumps(meta,ensure_ascii=False,indent=2), encoding='utf-8')
print(f"Built {len(docs)} Scratch SD bridges")
